#[allow(clippy::too_many_arguments)]
pub(crate) fn loop_expr_stmt(arena: &mut TermArena, expr: &Expr, span: &Span, path: &LoopPath, next: &mut Vec<LoopPath>, ends: &mut Vec<LoopEnd>, state: &[String], ints: &collections::BTreeSet<String>, pinned: &impl Fn(&str) -> Option<i64>, words: &winnow_grammar::InternerContext, claims: &collections::BTreeSet<(i64, i64)>, throwing: &impl Fn(&Expr) -> bool, holes_of: &impl Fn(&Expr) -> Vec<Expr>) -> Option<bool> {
    match expr {
        Expr::If { cond, then_branch, else_branch, .. } => {
            let cond = nikaia_std::boxed::open(cond);
            let c = loop_read(arena, cond, path, ints, pinned, words, true);
            let mut yes = path.clone();
            let mut no = path.clone();
            if c.is_some() {
                yes.constraints.push(nikaia_std::index::or(c, || 0));
                no.constraints.push(arena.not(nikaia_std::index::or(c, || 0)));
            }
            let after_yes = match loop_block(arena, then_branch, &vec![yes], ends, state, ints, pinned, words, claims, throwing, holes_of) { Some(__nikaia_value) => __nikaia_value, None => return None };
            next.extend(after_yes);
            let otherwise = match else_branch { Some(__nikaia_value) => __nikaia_value, None => {
                next.push(no);
                return Some(true);
            } };
            let after_no = match loop_block(arena, otherwise, &vec![no], ends, state, ints, pinned, words, claims, throwing, holes_of) { Some(__nikaia_value) => __nikaia_value, None => return None };
            next.extend(after_no);
            return Some(true);
        },
        Expr::Call { func, args, .. } => {
            let func = nikaia_std::boxed::open(func);
            if prover_an_assert_call(func, args, &span, claims) {
                let mut p = path.clone();
                let c = loop_read(arena, nikaia_std::index::get(&args, 0), &p, ints, pinned, words, true);
                if c.is_some() { p.constraints.push(nikaia_std::index::or(c, || 0)); }
                next.push(p);
                return Some(true);
            }
            return Some(false);
        },
        _ => return Some(false),
    }
}

pub(crate) fn loop_candidates(arena: &mut TermArena, record: &LoopRecord) -> Vec<(i64, String)> {
    let mut found: Vec<(i64, String)> = vec![];
    let start = record.start;
    let mut steady: Vec<(String, i64)> = vec![];
    for (name, deltas) in record.steps.iter() {
        if deltas.is_empty() { continue; }
        let k = *nikaia_std::index::get(&deltas, 0);
        let mut one = true;
        for d in deltas.iter() {
            let d = nikaia_std::num::value(d);
            if d != k { one = false; }
        }
        if one { steady.push((name.to_owned(), k)); }
    }
    for (name, k) in steady.iter() {
        let k = nikaia_std::num::value(k);
        let here = arena.var(name);
        let before = arena.var(&loop_before_name(name, start));
        if k == 0 { found.push((arena.equal(here, before), String::from("closed forms"))); } else if k > 0 { found.push((arena.ge(here, before), String::from("closed forms"))); } else { found.push((arena.le(here, before), String::from("closed forms"))); }
    }
    for i in 0..steady.len() as i64 {
        for j in i + 1..steady.len() as i64 {
            let (x, kx) = nikaia_std::index::get(&steady, (i) as usize); let kx = nikaia_std::num::value(kx);
            let (y, ky) = nikaia_std::index::get(&steady, nikaia_std::index::at(j)); let ky = nikaia_std::num::value(ky);
            if kx == 0 || ky == 0 { continue; }
            let left = loop_scaled_offset(arena, record, &x, ky);
            let right = loop_scaled_offset(arena, record, &y, kx);
            found.push((arena.equal(left, right), String::from("closed forms")));
        }
    }
    let c = nikaia_std::index::or(record.problem.condition, || -1);
    if c >= 0 {
        for (name, k) in steady.iter() {
            let k = nikaia_std::num::value(k);
            let bound = match loop_bound_of(&arena, c, name, &record.problem.state) { Some(__nikaia_value) => __nikaia_value, None => continue };
            let op = bound.op.to_owned();
            let e = bound.value;
            let here = arena.var(name);
            let before = arena.var(&loop_before_name(name, start));
            let kc = arena.int(k);
            let mut reach = arena.add(e, kc);
            let constant = arena.constant(e);
            if constant.is_some() { reach = arena.int(nikaia_std::index::or(constant, || 0) + k); }
            let mut near: Option<i64> = None;
            if k > 0 && op == "<" { near = Some(arena.lt(here, reach)); } else if k > 0 && op == "<=" { near = Some(arena.le(here, reach)); } else if k < 0 && op == ">" { near = Some(arena.gt(here, reach)); } else if k < 0 && op == ">=" { near = Some(arena.ge(here, reach)); }
            let n = match near { Some(__nikaia_value) => __nikaia_value, None => continue };
            found.push((n, String::from("closed forms")));
            let unmoved = arena.equal(here, before);
            found.push((arena.or(vec![n, unmoved]), String::from("closed forms")));
        }
    }
    for (name, deltas) in record.steps.iter() {
        let mut up = true;
        let mut down = true;
        let mut most: i64 = 0;
        let mut least: i64 = 0;
        for d in deltas.iter() {
            let d = nikaia_std::num::value(d);
            if d < 0 { up = false; }
            if d > 0 { down = false; }
            if d > most { most = d; }
            if d < least { least = d; }
        }
        if deltas.is_empty() || up && down { continue; }
        let ghost = loop_before_name(name, start);
        let known = match loop_known_value(&arena, &record.problem.fixed, &ghost) { Some(__nikaia_value) => __nikaia_value, None => continue };
        let here = arena.var(name);
        let at_start = arena.int(known);
        let limit = loop_constant_limit(&arena, c, name);
        if up {
            found.push((arena.ge(here, at_start), String::from("intervals")));
            let found_limit = match limit { Some(__nikaia_value) => __nikaia_value, None => continue };
            let op = found_limit.op.to_owned();
            let value = found_limit.value;
            let mut top: Option<i64> = None;
            if op == "<" { top = Some(value - 1 + most); } else if op == "<=" { top = Some(value + most); }
            let t = match top { Some(__nikaia_value) => __nikaia_value, None => continue };
            let highest = if t > known { t } else { known };
            let h = arena.int(highest);
            found.push((arena.le(here, h), String::from("intervals")));
        } else {
            found.push((arena.le(here, at_start), String::from("intervals")));
            let found_limit = match limit { Some(__nikaia_value) => __nikaia_value, None => continue };
            let op = found_limit.op.to_owned();
            let value = found_limit.value;
            let mut bottom: Option<i64> = None;
            if op == ">" { bottom = Some(value + 1 + least); } else if op == ">=" { bottom = Some(value + least); }
            let b = match bottom { Some(__nikaia_value) => __nikaia_value, None => continue };
            let lowest = if b < known { b } else { known };
            let l = arena.int(lowest);
            found.push((arena.ge(here, l), String::from("intervals")));
        }
    }
    found
}

pub(crate) fn loop_scaled_offset(arena: &mut TermArena, record: &LoopRecord, name: &str, k: i64) -> i64 {
    let ghost = loop_before_name(name, record.start);
    let here = arena.var(name);
    let known = loop_known_value(&arena, &record.problem.fixed, &ghost);
    let mut offset = here;
    if known.is_none() {
        let before = arena.var(&ghost);
        offset = arena.sub(here, before);
    } else if nikaia_std::index::or(known, || 0) != 0 {
        let before = arena.int(nikaia_std::index::or(known, || 0));
        offset = arena.sub(here, before);
    }
    if k == 1 { return offset; }
    let factor = arena.int(k);
    arena.mul(factor, offset)
}

pub(crate) fn loop_bound_of(arena: &TermArena, c: i64, name: &str, state: &[String]) -> Option<LoopBound> {
    let (op, left, right) = match arena.at(c) {
        SolverTerm::Lt(a, b) => ("<", a, b),
        SolverTerm::Le(a, b) => ("<=", a, b),
        SolverTerm::Gt(a, b) => (">", a, b),
        SolverTerm::Ge(a, b) => (">=", a, b),
        _ => return None,
    };
    let mut other = right;
    let mut turned = false;
    if arena.is_the_variable(left, name) { other = right; } else if arena.is_the_variable(right, name) {
        other = left;
        turned = true;
    } else { return None; }
    for s in state.iter() { if arena.mentions(other, s) { return None; } }
    if !turned { return Some(LoopBound { op: op.to_owned(), value: other }); }
    let flipped = if op == "<" { ">" } else if op == "<=" { ">=" } else if op == ">" { "<" } else { "<=" };
    Some(LoopBound { op: flipped.to_owned(), value: other })
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct LoopBound {
    pub(crate) op: String,
    pub(crate) value: i64,
}

pub(crate) fn loop_constant_limit(arena: &TermArena, c: i64, name: &str) -> Option<LoopBound> {
    if c < 0 { return None; }
    let none: Vec<String> = vec![];
    let bound = match loop_bound_of(arena, c, name, &none) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let value = match arena.constant(bound.value) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(LoopBound { op: bound.op.to_owned(), value })
}

pub(crate) fn loop_start_term(arena: &TermArena, facts: &[i64], name: &str) -> Option<i64> {
    for fact in facts.iter() {
        let fact = nikaia_std::num::value(fact);
        match arena.at(fact) {
            SolverTerm::Eq(a, b) => {
                if arena.is_the_variable(a, name) && !arena.text(b).contains('@') { return Some(b); }
                if arena.is_the_variable(b, name) && !arena.text(a).contains('@') { return Some(a); }
            },
            _ => { },
        }
    }
    None
}

pub(crate) fn loop_known_value(arena: &TermArena, facts: &[i64], name: &str) -> Option<i64> {
    for fact in facts.iter() {
        let fact = nikaia_std::num::value(fact);
        match arena.at(fact) {
            SolverTerm::Eq(a, b) => {
                if arena.is_the_variable(a, name) {
                    let v = arena.constant(b);
                    if v.is_some() { return std::convert::identity(v); }
                }
                if arena.is_the_variable(b, name) {
                    let v = arena.constant(a);
                    if v.is_some() { return std::convert::identity(v); }
                }
            },
            _ => { },
        }
    }
    None
}

pub fn loop_found(arena: &mut TermArena, record: &LoopRecord, proved: &impl Fn(&TermArena, &[i64], i64) -> bool, asked: &mut Vec<i64>) -> Option<LoopFound> {
    let mut kept: Vec<(i64, String)> = vec![];
    for (term, origin) in loop_candidates(arena, record) {
        let query = lg_loop_entry_query(&record.problem, term);
        asked.push(1);
        if proved(&arena, &query.facts, query.goal) { kept.push((term, origin.to_owned())); }
    }
    let mut rounds = 0;
    let mut changed = true;
    while changed && !kept.is_empty() && rounds < 4 {
        changed = false;
        rounds += 1;
        let mut all: Vec<i64> = vec![];
        for (term, _) in kept.iter() {
            let term = nikaia_std::num::value(term);
            all.push(term);
        }
        let assumed = arena.and(all);
        let mut still: Vec<(i64, String)> = vec![];
        for (term, origin) in kept.iter() {
            let term = nikaia_std::num::value(term);
            let mut query = lg_loop_turn_query(arena, &record.problem, assumed);
            query.goal = lg_loop_primed(arena, &record.problem, term);
            asked.push(1);
            if proved(&arena, &query.facts, query.goal) { still.push((term, origin.to_owned())); } else { changed = true; }
        }
        kept = still;
    }
    if kept.is_empty() || changed { return None; }
    let mut all: Vec<i64> = vec![];
    for (term, _) in kept.iter() {
        let term = nikaia_std::num::value(term);
        all.push(term);
    }
    let invariant = arena.and(all);
    let verdict = lg_loop_check(arena, &record.problem, invariant, proved);
    asked.push(2);
    if !verdict.proved() { return None; }
    Some(LoopFound { parts: kept })
}

pub fn loop_facts(arena: &mut TermArena, record: &LoopRecord, found: &LoopFound) -> Vec<i64> {
    let start = record.start;
    let mut renamed: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    let mut ghosts: Vec<String> = vec![];
    for name in record.problem.state.iter() {
        renamed.insert(name.to_owned(), arena.var(&loop_head_name(name, start)));
        if *name == record.counter { renamed.insert(lg_primed(name), arena.var(&loop_after_name(name, start))); } else { renamed.insert(lg_primed(name), arena.var(name)); }
        ghosts.push(loop_before_name(name, start));
    }
    let mut facts: Vec<i64> = vec![];
    for fact in record.problem.fixed.iter() {
        let fact = nikaia_std::num::value(fact);
        for g in ghosts.iter() {
            if arena.mentions(fact, g) {
                facts.push(fact);
                break;
            }
        }
    }
    for (term, _) in found.parts.iter() {
        let term = nikaia_std::num::value(term);
        facts.push(arena.substitute(term, &renamed));
    }
    let mut ways: Vec<i64> = vec![];
    for exit in record.problem.exits.iter() { if exit.kind != "return" { ways.push(arena.substitute(exit.relation, &renamed)); } }
    facts.push(arena.or(ways));
    facts
}

pub fn loop_found_text(arena: &mut TermArena, record: &LoopRecord, found: &LoopFound) -> String {
    let mut known: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    for name in record.problem.state.iter() {
        let ghost = loop_before_name(name, record.start);
        let value = match loop_start_term(&arena, &record.problem.fixed, &ghost) { Some(__nikaia_value) => __nikaia_value, None => continue };
        known.insert(ghost, value);
    }
    let mut parts: Vec<String> = vec![];
    let mut origins: Vec<String> = vec![];
    for (term, origin) in found.parts.iter() {
        let term = nikaia_std::num::value(term);
        let shown = arena.substitute(term, &known);
        let mut text = arena.text(shown);
        if text.contains(" || ") { text = format!("({})", text); }
        let mut said = nikaia_std::list::contains(&parts, &text);
        for other in parts.iter() { if text.starts_with(&format!("({} || ", other)) { said = true; } }
        if said { continue; }
        parts.push(text);
        if !nikaia_std::list::contains(&origins, &origin) { origins.push(origin.to_owned()); }
    }
    let changes = record.problem.state.join("`, `");
    format!("proved through the loop that changes `{}`, with the invariant `{}`, found by {} and checked by three queries", changes, parts.join(" && "), origins.join(" and "))
}

pub fn loop_open_text(records: &[LoopRecord]) -> String {
    let mut names: Vec<String> = vec![];
    for record in records.iter() { for n in record.problem.state.iter() { if !nikaia_std::list::contains(&names, &n) { names.push(n.to_owned()); } } }
    format!("nothing before it shows it; no invariant found for the loop that changes `{}` carries it", names.join("`, `"))
}

pub fn loop_reads(arena: &TermArena, facts: &[i64], claim: i64, records: &[LoopRecord]) -> bool {
    let mut names: collections::BTreeSet<String> = collections::BTreeSet::new();
    arena.variables(claim, &mut names);
    let mut used: collections::BTreeSet<i64> = collections::BTreeSet::new();
    let mut grew = true;
    while grew {
        grew = false;
        for record in records.iter() { for s in record.problem.state.iter() { if names.contains(s) { return true; } } }
        for k in 0..facts.len() as i64 {
            if used.contains(&k) { continue; }
            let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
            arena.variables(*nikaia_std::index::get(&facts, nikaia_std::index::at(k)), &mut read);
            let mut ties = false;
            for n in read.iter() {
                if names.contains(n) {
                    ties = true;
                    break;
                }
            }
            if ties {
                used.insert(k);
                for n in read.iter() {
                    if !names.contains(n) {
                        names.insert(n.to_owned());
                        grew = true;
                    }
                }
            }
        }
    }
    false
}

pub fn loop_key(arena: &TermArena, record: &LoopRecord) -> String {
    let mut parts: Vec<String> = vec![format!("{}", record.start)];
    for fact in record.problem.fixed.iter() {
        let fact = nikaia_std::num::value(fact);
        parts.push(arena.text(fact));
    }
    for fact in record.problem.entry.iter() {
        let fact = nikaia_std::num::value(fact);
        parts.push(arena.text(fact));
    }
    parts.push(arena.text(record.problem.step));
    parts.push(arena.text(nikaia_std::index::or(record.problem.condition, || record.problem.step.into())));
    for exit in record.problem.exits.iter() { parts.push(arena.text(exit.relation)); }
    parts.join(" ; ")
}

pub fn loop_parts_text(arena: &TermArena, found: &LoopFound) -> String {
    let mut parts: Vec<String> = vec![];
    for (term, origin) in found.parts.iter() {
        let term = nikaia_std::num::value(term);
        parts.push(format!("{}={}", origin.replace(' ', "-"), loop_term_word(arena, term)));
    }
    parts.join(";")
}

pub(crate) fn loop_term_word(arena: &TermArena, id: i64) -> String {
    match arena.at(id) {
        SolverTerm::Bool(b) => format!("{}", b),
        SolverTerm::Int(n) => format!("{}", n),
        SolverTerm::Var(ref name) => loop_name_word(name),
        SolverTerm::Add(a, b) => loop_pair_word(arena, "add", a, b),
        SolverTerm::Sub(a, b) => loop_pair_word(arena, "sub", a, b),
        SolverTerm::Neg(a) => format!("neg({})", loop_term_word(arena, a)),
        SolverTerm::Mul(a, b) => loop_pair_word(arena, "mul", a, b),
        SolverTerm::Quot(a, k) => format!("quot({},{})", loop_term_word(arena, a), k),
        SolverTerm::Le(a, b) => loop_pair_word(arena, "le", a, b),
        SolverTerm::Lt(a, b) => loop_pair_word(arena, "lt", a, b),
        SolverTerm::Ge(a, b) => loop_pair_word(arena, "ge", a, b),
        SolverTerm::Gt(a, b) => loop_pair_word(arena, "gt", a, b),
        SolverTerm::Eq(a, b) => loop_pair_word(arena, "eq", a, b),
        SolverTerm::Ne(a, b) => loop_pair_word(arena, "ne", a, b),
        SolverTerm::And(ref parts) => format!("and({})", loop_list_word(arena, &parts)),
        SolverTerm::Or(ref parts) => format!("or({})", loop_list_word(arena, &parts)),
        SolverTerm::Not(a) => format!("not({})", loop_term_word(arena, a)),
        _ => "?".to_string(),
    }
}

pub(crate) fn loop_pair_word(arena: &TermArena, op: &str, a: i64, b: i64) -> String { format!("{}({},{})", op, loop_term_word(arena, a), loop_term_word(arena, b)) }

pub(crate) fn loop_list_word(arena: &TermArena, parts: &[i64]) -> String {
    let mut words: Vec<String> = vec![];
    for p in parts.iter() {
        let p = nikaia_std::num::value(p);
        words.push(loop_term_word(arena, p));
    }
    words.join(",")
}

pub(crate) fn loop_name_word(name: &str) -> String { name.replace('%', "%25").replace('(', "%28").replace(')', "%29").replace(',', "%2C").replace(';', "%3B").replace('=', "%3D").replace('|', "%7C").replace(' ', "%20") }

pub(crate) fn loop_name_of(word: &str) -> Option<String> {
    if word.is_empty() || word.contains('?') { return None; }
    Some(word.replace("%20", " ").replace("%7C", "|").replace("%3D", "=").replace("%3B", ";").replace("%2C", ",").replace("%29", ")").replace("%28", "(").replace("%25", "%"))
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct LoopParsed {
    pub(crate) term: i64,
    pub(crate) rest: String,
}

pub(crate) fn loop_term_of(arena: &mut TermArena, word: &str) -> Option<LoopParsed> {
    let open = nikaia_std::index::or(nikaia_std::search::find(&word, &"(", 0), || (word.len() as i64).into());
    let comma = nikaia_std::index::or(nikaia_std::search::find(&word, &",", 0), || (word.len() as i64).into());
    let close = nikaia_std::index::or(nikaia_std::search::find(&word, &")", 0), || (word.len() as i64).into());
    let first = if open < comma { open } else { comma };
    let end = if first < close { first } else { close };
    let head = nikaia_std::index::get(&word, nikaia_std::index::at(0..end)).to_owned();
    let rest = nikaia_std::index::get(&word, nikaia_std::index::at(end..)).to_owned();
    if !rest.starts_with('(') {
        if head == "true" || head == "false" { return Some(LoopParsed { term: arena.boolean(head == "true"), rest }); }
        let n = text::parse_i64(&head);
        if n.is_some() { return Some(LoopParsed { term: arena.int(nikaia_std::index::or(n, || 0)), rest }); }
        let name = match loop_name_of(&head) { Some(__nikaia_value) => __nikaia_value, None => return None };
        return Some(LoopParsed { term: arena.var(&name), rest });
    }
    let mut after = nikaia_std::index::or(rest.strip_prefix('('), || "").to_owned();
    if head == "quot" {
        let inner = match loop_term_of(arena, &after) { Some(__nikaia_value) => __nikaia_value, None => return None };
        if !inner.rest.starts_with(',') { return None; }
        let tail = nikaia_std::index::or(inner.rest.strip_prefix(','), || "").to_owned();
        let shut = match nikaia_std::search::find(&tail, &")", 0) { Some(__nikaia_value) => __nikaia_value, None => return None };
        let k = match text::parse_i64(&nikaia_std::index::get(&tail, nikaia_std::index::at(0..shut)).to_owned()) { Some(__nikaia_value) => __nikaia_value, None => return None };
        if k <= 0 { return None; }
        return Some(LoopParsed { term: arena.quot(inner.term, k), rest: nikaia_std::index::get(&tail, nikaia_std::index::at(shut + 1..)).to_owned() });
    }
    let mut args: Vec<i64> = vec![];
    loop {
        let arg = match loop_term_of(arena, &after) { Some(__nikaia_value) => __nikaia_value, None => return None };
        args.push(arg.term);
        if arg.rest.starts_with(',') { after = nikaia_std::index::or(arg.rest.strip_prefix(','), || "").to_owned(); } else if arg.rest.starts_with(')') {
            after = nikaia_std::index::or(arg.rest.strip_prefix(')'), || "").to_owned();
            break;
        } else { return None; }
    }
    let term = match loop_built(arena, &head, args) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(LoopParsed { term, rest: after })
}

pub(crate) fn loop_built(arena: &mut TermArena, op: &str, args: Vec<i64>) -> Option<i64> {
    if op == "and" { return Some(arena.and(args)); }
    if op == "or" { return Some(arena.or(args)); }
    if args.len() == 1 {
        if op == "neg" { return Some(arena.neg(*nikaia_std::index::get(&args, 0))); }
        if op == "not" { return Some(arena.not(*nikaia_std::index::get(&args, 0))); }
        return None;
    }
    if args.len() != 2 { return None; }
    let a = *nikaia_std::index::get(&args, 0);
    let b = *nikaia_std::index::get(&args, 1);
    if op == "add" { return Some(arena.add(a, b)); }
    if op == "sub" { return Some(arena.sub(a, b)); }
    if op == "mul" { return Some(arena.mul(a, b)); }
    if op == "le" { return Some(arena.le(a, b)); }
    if op == "lt" { return Some(arena.lt(a, b)); }
    if op == "ge" { return Some(arena.ge(a, b)); }
    if op == "gt" { return Some(arena.gt(a, b)); }
    if op == "eq" { return Some(arena.equal(a, b)); }
    if op == "ne" { return Some(arena.unequal(a, b)); }
    None
}

pub fn loop_recorded(arena: &mut TermArena, record: &LoopRecord, recorded: &str, proved: &impl Fn(&TermArena, &[i64], i64) -> bool, asked: &mut Vec<i64>) -> Option<LoopFound> {
    let mut parts: Vec<(i64, String)> = vec![];
    let mut all: Vec<i64> = vec![];
    for part in recorded.split(';') {
        let at = match nikaia_std::search::find(&part, &"=", 0) { Some(__nikaia_value) => __nikaia_value, None => return None };
        let origin = nikaia_std::index::get(&part, nikaia_std::index::at(0..at)).replace('-', " ");
        let read = match loop_term_of(arena, &nikaia_std::index::get(&part, nikaia_std::index::at(at + 1..)).to_owned()) { Some(__nikaia_value) => __nikaia_value, None => return None };
        if !read.rest.is_empty() || origin.is_empty() { return None; }
        parts.push((read.term, origin));
        all.push(read.term);
    }
    if parts.is_empty() { return None; }
    let invariant = arena.and(all);
    let verdict = lg_loop_check(arena, &record.problem, invariant, proved);
    asked.push(2);
    if !verdict.proved() { return None; }
    Some(LoopFound { parts })
}

